<?php if(!$cart):?><section class="b2b-panel"><p>Korpa je prazna.</p></section><?php return;endif;$data=null;try{$data=partnerCartData($partner,$cart,$shippingId);}catch(RuntimeException $e){?><p class="b2b-error"><?=e($e->getMessage())?></p><?php }
if(!$data):?><section class="b2b-panel"><h2>Uredite korpu</h2><?php foreach($cart as $id=>$qty):$p=query('SELECT name FROM products WHERE id=?',[(int)$id])->fetch();?><form method="post" class="b2b-inline"><?=csrf()?><input type="hidden" name="action" value="cart_remove"><input type="hidden" name="product_id" value="<?=(int)$id?>"><span><?=e($p['name']??'Nedostupan artikal')?> · <?=(int)$qty?> kom.</span><button>Ukloni</button></form><?php endforeach;?></section><?php return;endif;?>
<section class="b2b-panel"><form method="post"><?=csrf()?><input type="hidden" name="action" value="cart_update"><div class="b2b-table-scroll"><table class="b2b-table"><thead><tr><th>Artikal</th><th>Osnovica / kom</th><th>Uslovi / kom</th><th>Vaša cijena</th><th>Količina</th><th>Ukupno</th></tr></thead><tbody><?php foreach($data['rows'] as [$product,$qty,$q]):?><tr><td><strong><?=e($product['name'])?></strong><small><?=e($product['sku'])?></small></td><td><?=partnerMoney($q['base'])?></td><td><small><?=e(partnerMode($q['mode']))?> <?=decimal($q['rate'])?>%<br><?=partnerMoney($q['adjustment'])?></small></td><td><?=partnerMoney($q['unit'])?></td><td><label class="b2b-sr-only" for="cart-qty-<?=(int)$product['id']?>">Količina za <?=e($product['name'])?></label><input class="b2b-qty" id="cart-qty-<?=(int)$product['id']?>" type="number" name="qty[<?=(int)$product['id']?>]" min="0" max="100" value="<?=$qty?>" required></td><td><strong><?=partnerMoney($q['unit']*$qty)?></strong></td></tr><?php endforeach;?></tbody></table></div><p class="b2b-muted">Količina 0 uklanja artikal. Nakon izmjene kliknite Ažuriraj korpu.</p><button>Ažuriraj korpu</button></form></section>
<div class="b2b-checkout-grid"><section class="b2b-panel"><h2>Dostava i kontakt</h2><form method="get"><input type="hidden" name="page" value="cart"><label for="shipping">Način dostave</label><select id="shipping" name="shipping"><?php foreach($shippingMethods as $method):?><option value="<?=(int)$method['id']?>" <?=$shippingId===(int)$method['id']?'selected':''?>><?=e($method['name'])?> · <?=partnerMoney(deliveryCharge($method))?></option><?php endforeach;?></select><button class="b2b-secondary">Izračunaj dostavu</button></form><hr><form method="post"><?=csrf()?><input type="hidden" name="action" value="checkout"><input type="hidden" name="shipping_id" value="<?=$shippingId?>"><input type="hidden" name="checkout_token" value="<?=e($_SESSION['partner_checkout_token'])?>"><input type="hidden" name="quote_hash" value="<?=e($data['hash'])?>"><?php foreach(['contact_name'=>['Kontakt osoba',180],'phone'=>['Telefon',60],'address'=>['Adresa isporuke',255],'city'=>['Grad',150]] as $key=>[$label,$max]):?><label for="delivery-<?=e($key)?>"><?=e($label)?></label><input id="delivery-<?=e($key)?>" name="<?=e($key)?>" maxlength="<?=$max?>" value="<?=e(is_string($_POST[$key]??null)?$_POST[$key]:$partner[$key])?>" required><?php endforeach;?><label for="delivery-note">Napomena / željeni termin</label><textarea id="delivery-note" name="note" maxlength="2000" rows="3"><?=e(is_string($_POST['note']??null)?$_POST['note']:'')?></textarea><p>Potvrda će biti poslana na <strong><?=e($partner['email'])?></strong>, kada je mail slanje podešeno.</p><button <?=$shippingMethods?'':'disabled'?>>Potvrdi narudžbu · <?=partnerMoney($data['total'])?></button></form></section><aside class="b2b-panel b2b-total-panel"><p class="b2b-kicker">VAŠ OBRAČUN</p><h2>Pregled iznosa</h2><dl class="b2b-totals"><div><dt>Zbir osnovica artikala</dt><dd><?=partnerMoney($data['base'])?></dd></div><div><dt>Artikli po vašim uslovima</dt><dd><?=partnerMoney($data['subtotal'])?></dd></div><div><dt>Dostava</dt><dd><?=partnerMoney($data['shipping'])?></dd></div><div class="b2b-grand"><dt>Ukupno za narudžbu</dt><dd><?=partnerMoney($data['total'])?></dd></div></dl><p class="b2b-muted">Osnovica je prodajna cijena za popust, odnosno nabavna cijena za maržu. Svaka stavka prikazuje svoj obračun; kombinacija različitih uslova prikazana je u tabeli.</p><p class="b2b-muted">Narudžba se može realizovati u više isporuka. Pregledajte isporučene i preostale količine u Mojim narudžbama.</p></aside></div>
